{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "trigger",
      "type": "ReactNode",
      "description": "Content shown in the trigger area (always visible).",
      "required": true,
      "slotElements": [
        {
          "__element": "Text",
          "props": {
            "type": "body"
          },
          "children": "Trigger"
        }
      ]
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Content that collapses and expands."
    },
    {
      "name": "defaultIsOpen",
      "type": "boolean",
      "description": "Default open state for standalone uncontrolled usage. Ignored when value binds the item to a surrounding CollapsibleGroup.",
      "default": "true"
    },
    {
      "name": "isOpen",
      "type": "boolean",
      "description": "Controlled open state for standalone usage. Ignored when value binds the item to a surrounding CollapsibleGroup."
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disable the item so its trigger can't be toggled (dimmed, aria-disabled, and out of the tab order). Doesn't collapse an already-open item.",
      "default": "false"
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Callback invoked when standalone open state changes. A surrounding CollapsibleGroup owns grouped state and calls its onChange instead."
    },
    {
      "name": "chevronPosition",
      "type": "'start' | 'end'",
      "description": "Logical position of Collapsible's disclosure chevron. `end` (default) follows the label, pointing down when collapsed and up when expanded. `start` precedes the label, pointing inward toward content when collapsed (mirrored under RTL) and down when expanded. Inside a CollapsibleGroup this defaults to the group's chevronPosition.",
      "default": "'end'"
    },
    {
      "name": "value",
      "type": "string",
      "description": "Identifier used for group coordination. When set inside a CollapsibleGroup, the group owns open state and its onChange is the notification callback."
    },
    {
      "name": "animatedLayout",
      "type": "AnimatedLayout",
      "description": "The handle from useAnimatedLayout({containerRef}). With it, opening and closing glides the content after this Collapsible, up to that container, on one shared motion role instead of jumping, and the revealed content and the chevron move on the same motion. Without it, the content after it takes its place at once."
    },
    {
      "name": "ref",
      "type": "React.Ref<HTMLDivElement>",
      "description": "Ref forwarded to the root collapsible element."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization. Must be a stylex.create() value."
    },
    {
      "name": "className",
      "type": "string",
      "description": "CSS class name for the root element. Prefer xstyle for styling."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles. Prefer xstyle for StyleX-optimized styling."
    },
    {
      "name": "data-testid",
      "type": "string",
      "description": "Test selector for automated testing frameworks."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
